// Phase 1 GO test: call one mapped engine function in the Mac x86_64 slice and check its results
// against upstream's own expectation table.
//   Windows 0x64fe90  unsigned(*)(unsigned)  (team-instruction value -> option bit)
//   Mac x86_64 0x55afb0 (port/map/rva_map.json: verified; callgraph+const+consts_sim)
// Expected bits: native/fm27_tactic_bindings.h fm27_team_options[] (generated by upstream from the
// original native resolver). The game install is used read-only; nothing is patched.
#include <dlfcn.h>
#include <mach-o/dyld.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include "../../native/fm27_tactic_bindings.h"

#if !defined(__x86_64__)
#error "RVA is for the x86_64 slice; build with -arch x86_64"
#endif

static const uintptr_t MAC_X86_64_OPTION_BIT = 0x55afb0;

int main(int argc, char** argv) {
    const char* path = argc > 1 ? argv[1] : nullptr;
    if (!path) { fprintf(stderr, "usage: go_test <game_plugin>\n"); return 2; }
    void* h = dlopen(path, RTLD_NOW | RTLD_LOCAL);
    if (!h) { fprintf(stderr, "dlopen failed: %s\n", dlerror()); return 1; }
    const unsigned char* base = nullptr;
    for (uint32_t i = 0; i < _dyld_image_count(); i++)
        if (strstr(_dyld_get_image_name(i), "/game_plugin.bundle/Contents/MacOS/game_plugin"))
            base = (const unsigned char*)_dyld_get_image_header(i);
    if (!base) { fprintf(stderr, "game_plugin image not found\n"); return 1; }
    printf("game_plugin base %p\n", (const void*)base);

    auto option_bit = (unsigned (*)(unsigned))(base + MAC_X86_64_OPTION_BIT);
    unsigned pass = 0, fail = 0;
    for (const auto& o : fm27_team_options) {
        unsigned got = option_bit(o.value);
        char tag[5] = {(char)(o.value >> 24), (char)(o.value >> 16), (char)(o.value >> 8), (char)o.value, 0};
        if (got == o.bit) pass++;
        else { fail++; printf("MISMATCH group %u value %u '%s': expected bit %u, got %u\n", o.group, o.value, tag, o.bit, got); }
    }
    printf("RESULT %u/%zu match, %u mismatch\n", pass, sizeof(fm27_team_options) / sizeof(fm27_team_options[0]), fail);
    return fail ? 3 : 0;
}
